class Program
{
    static void Main()
    {
        (x1, string y1) = new A();
        int x1;
        (int x2, y2) = new A();
        string y2;
        (int x3, (string y3, z3)) = new B();
        bool z3;
        (x4, var (y4, z4)) = new B();
        int x4;
    }
}

class A
{
    public void Deconstruct(out int a, out string b)
    {
        a = 1;
        b = "hello";
    }
}

class B
{
    public void Deconstruct(out int a, out (string b, bool c) tuple)
    {
        a = 1;
        tuple = ("hello", true);
    }
}

